138	 * 終了コードが okCodes なら成功、findingCodes なら指摘あり、それ以外と起動の失敗は ExecutionError にする
139	 */
140	function runBin(
141	  cache: CachePaths,
142	  name: string,
143	  args: readonly string[],
144	  cwd: string,
145	  env: NodeJS.ProcessEnv,
146	  findingCodes: readonly number[],
147	): ToolResult {
148	  const bin = join(cache.nodeModulesDir, ".bin", name);
149	  const r = spawnSync(process.execPath, [bin, ...args], { cwd, env, encoding: "utf8" });
150	  if (r.error !== undefined) {
151	    throw new ExecutionError(`${name} を実行できない (${bin}): ${r.error.message}`);
152	  }
153	  const output = `${r.stdout}${r.stderr}`.trimEnd();
154	  if (r.status === 0) return { ok: true, output };
155	  if (r.status !== null && findingCodes.includes(r.status)) return { ok: false, output };
156	  throw new ExecutionError(
157	    `${name} が終了コード ${String(r.status)} (シグナル ${String(r.signal)}) で終了した (${bin}):\n${output}`,
158	  );
159	}
