234	  if (e === "title") return "題名";
235	  if (e === "takeaway") return "一言";
236	  return `deck.ts の要素 ${String(e)} (スライドの要素の配列の添字。足した順に 0 から数える)`;
237	}
238	
239	function formatFitIssue(i: FitIssue): string {
240	  return `${i.key} の${describeFitElement(i.element)}: 要る高さ ${i.need.toFixed(2)} インチ、文字を置ける高さ ${i.height.toFixed(2)} インチ、文字の先頭 ${JSON.stringify(i.head)}`;
241	}
242	
243	/**
244	 * 資料のディレクトリを検査する。検査の順序と、指摘があったときに後の検査をするかは次のとおり。
245	 * 1. 構成案の書式と【提案】の残り。
246	 * 2. tsc と eslint。どちらかに指摘があれば、資料ごとのスクリプトを実行せずに終える。
247	 * 3. 資料ごとのスクリプトの実行と、テーマの値。
248	 * 4. 構成案と資料ごとのスクリプトのキーの突き合わせ (構成案に書式の誤りが無いときだけ)。
249	 * 5. はみ出しの見積もり (キーが一致し、テーマに誤りが無いときだけ)。
250	 * 資料のディレクトリやファイルが無い・ライブラリが入っていない・ツールを実行できないときは、ExecutionError を送出する
251	 */
252	export async function checkDeck(deckDir: string, options: CheckOptions = {}): Promise<CheckReport> {
253	  const pluginDir = options.pluginDir ?? PLUGIN_DIR;
254	  const env = options.env ?? process.env;
255	  const paths = deckPaths(deckDir);
256	  const cache = installedCache({ pluginDir, env });
257	  prepareBuildDir(paths, pluginDir);
258	  const findings: Finding[] = [];
259	
260	  const parsed = parseOutline(readFileSync(paths.outline, "utf8"));
261	  if (!parsed.ok) {
262	    findings.push({ heading: "構成案 outline.md の書式の誤り", lines: parsed.errors.map(formatOutlineError) });
263	  } else if (parsed.outline.proposals.length > 0) {
264	    findings.push({
265	      heading: "【提案】が付いたままのスライド (採否を決め、採用するなら【提案】を外し、採用しないならスライドを消す)",
266	      lines: parsed.outline.proposals.map((s) => `${String(s.line)} 行目: ${s.key}: ${s.title}`),
267	    });
268	  }
269	
270	  const tsc = typeCheck(paths, cache, env);
271	  if (!tsc.ok) findings.push({ heading: "tsc の指摘", lines: tsc.output.split("\n") });
272	  const eslint = lint(paths, cache, env, pluginDir);
273	  if (!eslint.ok) findings.push({ heading: "eslint の指摘", lines: eslint.output.split("\n") });
274	  if (!tsc.ok || !eslint.ok) return { findings, deck: null };
275	
276	  const loaded = await loadDeckScript(paths);
277	  if (!loaded.ok) {
278	    findings.push({ heading: "deck.ts を実行できない", lines: loaded.message.split("\n") });
279	    return { findings, deck: null };
280	  }
281	  const themeErrors = checkTheme(loaded.result.theme);
282	  if (themeErrors.length > 0) findings.push({ heading: "deck.ts のテーマの誤り", lines: themeErrors });
283	  if (!parsed.ok) return { findings, deck: null };
284	
285	  const outline = parsed.outline;
286	  const mismatch = matchKeys(
287	    outline.slides.map((s) => s.key),
288	    loaded.result.slides.map((f) => f.key),
289	  );
290	  if (hasMismatch(mismatch)) {
291	    const lines: string[] = [];
292	    if (mismatch.outlineOnly.length > 0) lines.push(`構成案にだけあるキー: ${mismatch.outlineOnly.join(", ")}`);
293	    if (mismatch.deckOnly.length > 0) lines.push(`deck.ts にだけあるキー: ${mismatch.deckOnly.join(", ")}`);
294	    if (mismatch.deckDuplicates.length > 0) {
295	      lines.push(`deck.ts で 2 回以上図を作ったキー: ${mismatch.deckDuplicates.join(", ")}`);
296	    }
297	    findings.push({ heading: "構成案と deck.ts のキーの不一致", lines });
298	    return { findings, deck: null };
299	  }
300	  if (themeErrors.length > 0) return { findings, deck: null };
301	
302	  const deck = assembleDeck(outline, loaded.result);
303	  const fit = estimateSlides(deck.slides);
304	  if (fit.length > 0) {
305	    findings.push({ heading: "文字が箱からはみ出しそうな箇所 (箱を広げるか、文を縮める)", lines: fit.map(formatFitIssue) });
306	  }
307	  return { findings, deck: findings.length === 0 ? deck : null };
308	}
309	
310	/** 検査の結果を、利用者に示す文字列にする。指摘が無ければ、スライドの枚数を示す */
311	export function formatCheckReport(report: CheckReport): string {
312	  if (report.deck !== null) {
313	    return `検査の指摘は無い (スライド ${String(report.deck.slides.length)} 枚)\n`;
314	  }
315	  return report.findings.map((f) => `${f.heading}:\n${f.lines.map((l) => `  ${l}`).join("\n")}\n`).join("\n");
316	}
