1	// スライドのデータから、pptxgenjs で PowerPoint のファイルを書く (計画の R8・R11・U5)。
2	// pptxgenjs は、キャッシュの node_modules を起点にした createRequire で読み込む (計画の KTD8)。
3	// テーマの色は pptxgenjs では書けないので、書いた後に pptx のスキルの scripts/apply_theme.js で書き込む (ファイル src/pptx/build.ts)。
4	
5	import { createRequire } from "node:module";
6	import { join } from "node:path";
7	import type PptxGenJS from "pptxgenjs";
8	import { title as titleBox, takeaway as takeawayBox, slide as emptyFigure } from "../data/parts.ts";
9	import type { SchemeColorName, Theme } from "../data/theme.ts";
10	import { schemeColorValues } from "../data/theme.ts";
11	import {
12	  type Deck,
13	  type LineElement,
14	  type Margin,
15	  type Paragraph,
16	  type ShapeElement,
17	  SLIDE_SIZE,
18	  type Slide,
19	  type SlideFigure,
20	  type TextBody,
21	  type TextBoxElement,
22	  type ThemeColorName,
23	} from "../data/types.ts";
24	
25	/** pptxgenjs のクラス */
26	export type PptxGenConstructor = typeof PptxGenJS;
27	
28	type Presentation = PptxGenJS;
29	type PptxSlide = PptxGenJS.Slide;
30	
31	/** キャッシュの node_modules から pptxgenjs を読み込む */
32	export function loadPptxGen(nodeModulesDir: string): PptxGenConstructor {
33	  // createRequire の起点は、そのディレクトリの中のファイルのパスで渡す (ファイルは無くてよい)
34	  const require = createRequire(join(nodeModulesDir, "slide-deck-pptx.cjs"));
35	  const loaded: unknown = require("pptxgenjs");
36	  if (typeof loaded !== "function") {
37	    throw new Error(`${nodeModulesDir} の pptxgenjs が、クラスを書き出していない`);
38	  }
39	  // pptxgenjs の CommonJS の入口は、クラス PptxGenJS そのものを書き出す
40	  return loaded as PptxGenConstructor;
41	}
42	
43	/** 題名のプレースホルダーを持つレイアウトの名前 */
44	export const CONTENT_LAYOUT = "SLIDE_DECK_CONTENT";
45	
46	// スライドの大きさのレイアウトの名前。大きさは SLIDE_SIZE から決める
47	const SLIDE_LAYOUT = "SLIDE_DECK_16x9";
48	
49	// 箇条書きの字下げ (ポイント)。Google スライドの字下げ (計画の KTD14) と、はみ出しの見積もり (計画の KTD6) と同じ値
50	const BULLET_INDENT_PT = 16;
51	
52	/**
53	 * テーマの色の名前を、pptxgenjs の色の名前にする。
54	 * pptxgenjs は、tx1・tx2・bg1・bg2・accent1〜6 だけをテーマの色 (a:schemeClr) として書き、ほかの文字列は RGB の値として書く。
55	 * PowerPoint のファイルのマスターは tx1 を dk1 に、bg1 を lt1 に対応させる (要素 p:clrMap) ので、同じ色になる
56	 */
57	export function schemeColor(name: ThemeColorName): string {
58	  switch (name) {
59	    case "dk1":
60	      return "tx1";
61	    case "lt1":
62	      return "bg1";
63	    case "dk2":
64	      return "tx2";
65	    case "lt2":
66	      return "bg2";
67	    default:
68	      return name;
69	  }
70	}
71	
72	/** 内側の余白を、pptxgenjs のオプション margin の順序 [左, 右, 下, 上] (ポイント) にする */
73	function toPptxMargin(m: Margin): [number, number, number, number] {
74	  return [m.left, m.right, m.bottom, m.top];
75	}
76	
77	/**
78	 * 段落を、pptxgenjs の文字の部分の配列にする。段落の分け方は部品の関数が決めたものをそのまま使い、pptxgenjs に任せない
79	 * (型 RunInput の説明)。各段落の最後の部分に breakLine を付け、最後の段落だけは付けない。
80	 * 部品の関数は横の揃え方を必ず決めるので、pptxgenjs は breakLine でだけ段落を区切る
81	 */
82	export function toTextProps(paragraphs: readonly Paragraph[]): PptxGenJS.TextProps[] {
83	  const props: PptxGenJS.TextProps[] = [];
84	  paragraphs.forEach((p, pi) => {
85	    p.runs.forEach((r, ri) => {
86	      const options: PptxGenJS.TextPropsOptions = {
87	        fontSize: r.fontSize,
88	        bold: r.bold,
89	        color: schemeColor(r.color),
90	        bullet: p.bullet ? { indent: BULLET_INDENT_PT } : false,
91	        breakLine: ri === p.runs.length - 1 && pi < paragraphs.length - 1,
92	      };
93	      if (r.link !== null) options.hyperlink = { url: r.link };
94	      props.push({ text: r.text, options });
95	    });
96	  });
97	  return props;
98	}
99	
100	/** 文字の箱の書式 (段落の分け方以外) を、pptxgenjs のオプションにする */
101	function textBodyOptions(body: TextBody): PptxGenJS.TextPropsOptions {
102	  return {
103	    align: body.align,
104	    valign: body.valign,
105	    margin: toPptxMargin(body.margin),
106	    paraSpaceAfter: body.paraSpaceAfter,
107	  };
108	}
109	
110	function lineOptions(color: ThemeColorName, width: number, dashed: boolean): PptxGenJS.ShapeLineProps {
111	  return { color: schemeColor(color), width, dashType: dashed ? "dash" : "solid" };
112	}
113	
114	function addShape(pres: Presentation, s: PptxSlide, e: ShapeElement): void {
115	  const options: PptxGenJS.TextPropsOptions = {
116	    shape: pres.ShapeType[e.shape],
117	    x: e.x,
118	    y: e.y,
119	    w: e.w,
120	    h: e.h,
121	    fill: { color: schemeColor(e.fill.color), transparency: e.fill.transparency },
122	  };
123	  if (e.shape === "roundRect") options.rectRadius = e.radius;
124	  if (e.outline !== null) options.line = lineOptions(e.outline.color, e.outline.width, e.outline.dashed);
125	  if (e.name !== null) options.objectName = e.name;
126	  if (e.text === null) {
127	    s.addShape(pres.ShapeType[e.shape], options);
128	    return;
129	  }
130	  s.addText(toTextProps(e.text.paragraphs), { ...options, ...textBodyOptions(e.text) });
131	}
132	
133	function addTextBox(s: PptxSlide, e: TextBoxElement): void {
134	  const options: PptxGenJS.TextPropsOptions = {
135	    x: e.x,
136	    y: e.y,
137	    w: e.w,
138	    h: e.h,
139	    isTextBox: true,
140	    ...textBodyOptions(e.text),
141	  };
142	  if (e.name !== null) options.objectName = e.name;
143	  s.addText(toTextProps(e.text.paragraphs), options);
144	}
145	
146	function addLine(pres: Presentation, s: PptxSlide, e: LineElement): void {
147	  // 矢じりは、始点 (beginArrowType) と終点 (endArrowType) に付ける。
148	  // 型 LineElement の endArrow は終点、startArrow は始点の矢じり (型の説明)
149	  const line: PptxGenJS.ShapeLineProps = lineOptions(e.color, e.width, e.dashed);
150	  if (e.endArrow) line.endArrowType = "triangle";
151	  if (e.startArrow) line.beginArrowType = "triangle";
152	  s.addShape(pres.ShapeType.line, { x: e.x, y: e.y, w: e.w, h: e.h, flipH: e.flipH, flipV: e.flipV, line });
153	}
154	
155	/** 部品の関数 title か takeaway が作る文字の箱を取り出す */
156	function fixedBox(add: (s: SlideFigure, t: string) => void, key: string, t: string): TextBoxElement {
157	  const fig = emptyFigure(key);
158	  add(fig, t);
159	  const [box] = fig.elements;
160	  if (box?.kind !== "textBox") throw new Error(`題名か一言の部品の関数が、文字の箱を作らなかった (キー ${key})`);
161	  return box;
162	}
163	
164	/**
165	 * 題名のプレースホルダーを持つレイアウトを作る。位置と書式は、部品の関数 title が作る箱と同じにする
166	 * (計画の KTD1。はみ出しの見積もりと Google スライドの指示の作成も、同じ箱を使う)
167	 */
168	function defineContentLayout(pres: Presentation): void {
169	  const box = fixedBox(titleBox, "layout", "");
170	  const [run] = box.text.paragraphs[0]?.runs ?? [];
171	  if (run === undefined) throw new Error("題名の部品の関数が、文字の部分を作らなかった");
172	  pres.defineSlideMaster({
173	    title: CONTENT_LAYOUT,
174	    // 背景をテーマの lt1 (背景の色) で塗る。背景を書かないと、PowerPoint のファイルを表示するソフトによって背景の色が違う
175	    // (macOS の Quick Look では灰色になった)
176	    background: { color: schemeColor("lt1") },
177	    objects: [
178	      {
179	        placeholder: {
180	          options: {
181	            name: "title",
182	            type: "title",
183	            x: box.x,
184	            y: box.y,
185	            w: box.w,
186	            h: box.h,
187	            fontSize: run.fontSize,
188	            bold: run.bold,
189	            color: schemeColor(run.color),
190	            align: box.text.align,
191	            valign: box.text.valign,
192	            margin: toPptxMargin(box.text.margin),
193	          },
194	          text: "",
195	        },
196	      },
197	    ],
198	  });
199	}
200	
201	function addSlide(pres: Presentation, slide: Slide): void {
202	  const s = pres.addSlide({ masterName: CONTENT_LAYOUT });
203	  const title = fixedBox(titleBox, slide.key, slide.title);
204	  s.addText(toTextProps(title.text.paragraphs), { placeholder: "title" });
205	  for (const e of slide.elements) {
206	    switch (e.kind) {
207	      case "shape":
208	        addShape(pres, s, e);
209	        break;
210	      case "textBox":
211	        addTextBox(s, e);
212	        break;
213	      case "line":
214	        addLine(pres, s, e);
215	        break;
216	    }
217	  }
218	  addTextBox(s, fixedBox(takeawayBox, slide.key, slide.takeaway));
219	  if (slide.notes !== "") s.addNotes(slide.notes);
220	}
221	
222	/**
223	 * スライドのデータから PowerPoint のファイルを作り、内容を返す。
224	 * スライドの大きさは SLIDE_SIZE。テーマのフォントは書くが、テーマの色は書かない (pptxgenjs が書けないため。テーマの色は、ファイル src/pptx/build.ts が pptx のスキルで書き込む)
225	 */
226	export async function renderPptx(deck: Deck, PptxGen: PptxGenConstructor): Promise<Buffer> {
227	  const pres = new PptxGen();
228	  pres.defineLayout({ name: SLIDE_LAYOUT, width: SLIDE_SIZE.w, height: SLIDE_SIZE.h });
229	  pres.layout = SLIDE_LAYOUT;
230	  pres.title = deck.title;
231	  pres.theme = { headFontFace: deck.theme.fonts.heading, bodyFontFace: deck.theme.fonts.body };
232	  defineContentLayout(pres);
233	  for (const slide of deck.slides) addSlide(pres, slide);
234	  const out = await pres.write({ outputType: "nodebuffer" });
235	  if (!Buffer.isBuffer(out)) throw new Error("pptxgenjs が、ファイルの内容を Buffer で返さなかった");
236	  return out;
237	}
