239	/** pptx のスキルの scripts/apply_theme.js に渡すテーマ。名前と、テーマの 12 色 (16 進数 6 桁) */
240	export interface ApplyThemeInput {
241	  name: string;
242	  headFontFace: string;
243	  bodyFontFace: string;
244	  colors: Record<SchemeColorName, string>;
