247	/** テーマを、pptx のスキルの scripts/apply_theme.js に渡す形にする */
248	export function applyThemeInput(theme: Theme): ApplyThemeInput {
249	  return {
250	    name: theme.name,
251	    headFontFace: theme.fonts.heading,
252	    bodyFontFace: theme.fonts.body,
253	    colors: schemeColorValues(theme),
254	  };
