7	import { spawnSync } from "node:child_process";
8	import { existsSync, rmSync, statSync, writeFileSync } from "node:fs";
9	import { join, resolve } from "node:path";
10	import { type CheckOptions, type CheckReport, checkDeck, deckPaths, ExecutionError, installedCache } from "../check/deck.ts";
11	import { type CachePaths, venvState } from "../setup/setup.ts";
12	import { applyThemeInput, loadPptxGen, renderPptx } from "./write.ts";
13	
14	/** pptx のスキルのディレクトリと、使う 2 つのスクリプトのパス */
15	export interface PptxSkill {
16	  readonly dir: string;
17	  /** scripts/apply_theme.js */
18	  readonly applyTheme: string;
19	  /** scripts/office/validate.py */
20	  readonly validate: string;
21	}
