23	/** pptx のスキルのディレクトリを受け取り、使う 2 つのスクリプトがあることを確認する。無ければ ExecutionError を送出する */
24	export function pptxSkill(dir: string): PptxSkill {
25	  const abs = resolve(dir);
26	  const skill: PptxSkill = {
27	    dir: abs,
28	    applyTheme: join(abs, "scripts", "apply_theme.js"),
29	    validate: join(abs, "scripts", "office", "validate.py"),
30	  };
31	  const missing = [skill.applyTheme, skill.validate].filter((p) => !existsSync(p));
32	  if (missing.length > 0) {
33	    throw new ExecutionError(
34	      `pptx のスキルのディレクトリ ${abs} に、次のファイルが無い:\n${missing.map((p) => `  ${p}`).join("\n")}\n` +
35	        "Claude のデスクトップアプリが配る pptx のスキル (スキルの一覧での名前は anthropic-skills:pptx) のディレクトリを渡す。" +
36	        "マーケットプレイス anthropic-agent-skills のプラグイン document-skills が配る pptx のスキルには、scripts/apply_theme.js が無い",
37	    );
38	  }
39	  return skill;
40	}
