42	/**
43	 * テーマの色を PowerPoint のファイルに書き込む処理。pptxPath のファイルを書き換え、利用者に示す出力を返す。
44	 * 失敗したら ExecutionError を送出する。テストで差し替えられるよう、関数として渡す
45	 */
46	export type ApplyTheme = (pptxPath: string, themePath: string) => string;
47	
48	/**
49	 * pptx のスキルの scripts/apply_theme.js を、環境変数 NODE_PATH にキャッシュの node_modules を指定した子プロセスで実行する
50	 * (計画の KTD8)。apply_theme.js は pptxgenjs に同梱の jszip を、require で NODE_PATH から探す
51	 */
52	export function skillApplyTheme(skill: PptxSkill, cache: CachePaths, env: NodeJS.ProcessEnv): ApplyTheme {
53	  return (pptxPath, themePath) => {
54	    const r = spawnSync(process.execPath, [skill.applyTheme, pptxPath, themePath], {
55	      env: { ...env, NODE_PATH: cache.nodeModulesDir },
56	      encoding: "utf8",
57	    });
58	    const output = `${r.stdout}${r.stderr}`.trimEnd();
59	    if (r.error !== undefined || r.status !== 0) {
60	      throw new ExecutionError(
61	        `pptx のスキルの ${skill.applyTheme} が失敗した (終了コード ${String(r.status)}${r.error === undefined ? "" : `、${r.error.message}`}):\n${output}`,
62	      );
63	    }
64	    return output;
65	  };
66	}
67	
68	/** pptx のスキルの scripts/office/validate.py の結果。ok が false なら、形式の誤りがある */
69	export interface ValidateResult {
70	  readonly ok: boolean;
71	  readonly output: string;
72	}
73	
74	/**
75	 * pptx のスキルの scripts/office/validate.py を、キャッシュの venv の Python で実行する。
76	 * 終了コード 0 は誤りなし、1 は形式の誤りあり。それ以外は ExecutionError にする
77	 */
78	export function skillValidate(skill: PptxSkill, cache: CachePaths, pptxPath: string, env: NodeJS.ProcessEnv): ValidateResult {
