112	 */
113	function removePreviousPptx(deckDir: string): void {
114	  const dir = resolve(deckDir);
115	  if (!existsSync(dir) || !statSync(dir).isDirectory()) return;
116	  const pptxPath = join(dir, "build", "deck.pptx");
117	  try {
118	    rmSync(pptxPath, { force: true });
119	  } catch (e) {
