126	 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
127	 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
128	 */
129	export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
130	  removePreviousPptx(deckDir);
131	  const env = options.env ?? process.env;
132	  const skill = pptxSkill(options.skillDir);
133	  const cache = installedCache(options);
134	  if (venvState(cache) !== "installed") {
135	    throw new ExecutionError(
136	      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
137	        "サブコマンド setup status で状態を確認し、setup install で入れる",
138	    );
139	  }
140	  const paths = deckPaths(deckDir);
141	  const pptxPath = join(paths.buildDir, "deck.pptx");
142	  const themePath = join(paths.buildDir, "theme.json");
143	
144	  const check = await checkDeck(deckDir, options);
145	  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };
146	
147	  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
148	  writeFileSync(themePath, `${JSON.stringify(applyThemeInput(check.deck.theme), null, 2)}\n`);
149	  const applyTheme = options.applyTheme ?? skillApplyTheme(skill, cache, env);
150	  let applyThemeOutput: string;
151	  try {
152	    applyThemeOutput = applyTheme(pptxPath, themePath);
153	  } catch (e) {
154	    rmSync(pptxPath, { force: true });
155	    const message = e instanceof Error ? e.message : String(e);
156	    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
157	  }
158	  const validate = skillValidate(skill, cache, pptxPath, env);
159	  return { check, pptx: pptxPath, applyThemeOutput, validate };
160	}
